@push('scripts')
<script>
document.addEventListener('DOMContentLoaded',()=>{
const dialog=document.getElementById('cpDialog'),body=document.getElementById('cpDialogBody');
const url=@json(route($ruta.'.cumplimiento-agencias.detalle'));
const filtros={agencia_id:@json($agenciaId),receptor_id:@json($receptorId)};
const escape=s=>String(s??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
document.getElementById('cpDialogClose').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
document.querySelectorAll('.js-cp-detail').forEach(btn=>btn.addEventListener('click',async()=>{
document.getElementById('cpDialogTitle').textContent=btn.dataset.titulo;
document.getElementById('cpDialogDate').textContent=btn.dataset.fecha;
body.textContent='Cargando información…';dialog.showModal();
const p=new URLSearchParams({fecha:btn.dataset.fecha,categoria:btn.dataset.categoria});
Object.entries(filtros).forEach(([k,v])=>{if(v!==null)p.set(k,v)});
try{const response=await fetch(url+'?'+p.toString(),{headers:{Accept:'application/json'},credentials:'same-origin'});if(!response.ok)throw Error('Consulta no disponible');const data=await response.json();
if(!data.jornadas.length){body.textContent='No se encontraron turnos para esta categoría.';return}
body.innerHTML='<div style="overflow-x:auto"><table class="cp-table"><thead><tr><th>Fecha</th><th>Agencia</th><th>Ventanilla</th><th>Receptor</th><th>Turno</th><th>Arqueo</th><th>Certificación</th></tr></thead><tbody>'+data.jornadas.map(j=>'<tr>'+[j.fecha,j.agencia,j.ventanilla,j.receptor,j.turno,j.arqueo,j.certificacion==='CERTIFICADO'?'Certificado':j.certificacion==='PENDIENTE_CERTIFICACION'?'Pendiente':'No aplica'].map(v=>'<td>'+escape(v)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';
}catch(e){body.textContent='No fue posible cargar el detalle. Intenta nuevamente.'}
}));
});
</script>
@endpush
